// Case Study Follow-up - Build 3 email tasks (Australia/Sydney timezone)
// v2: writes to postgres-tos task_queue (no Task ID generation; bigserial assigns)
const raw = $input.item.json;
const webhook = raw.body || raw;

function formatDateTimeAuSydney(date) {
  const auDate = new Date(date.getTime() + (11 * 60 * 60 * 1000));
  const year = auDate.getUTCFullYear();
  const month = String(auDate.getUTCMonth() + 1).padStart(2, '0');
  const day = String(auDate.getUTCDate()).padStart(2, '0');
  const hours = String(auDate.getUTCHours()).padStart(2, '0');
  const minutes = String(auDate.getUTCMinutes()).padStart(2, '0');
  const seconds = String(auDate.getUTCSeconds()).padStart(2, '0');
  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

const now = new Date();
const delays = [0, 3, 7]; // days — was hardcoded in v1, preserved

const templatePayload = {
  first_name: webhook.first_name,
  company_name: webhook.company_name,
  industry: webhook.industry,
  case_study_name: webhook.case_study_name
};

return delays.map((d, i) => {
  const scheduled = new Date(now.getTime() + (d * 24 * 60 * 60 * 1000));
  return {
    json: {
      kind: 'email_send',
      payload: {
        source_workflow: 'case-study-followup-sequence',
        template_name: `case_study_email_${i + 1}`,
        contact_id: webhook.contact_id,
        contact_email: webhook.email,
        contact_name: webhook.first_name,
        scheduled_for: formatDateTimeAuSydney(scheduled),
        template_payload: templatePayload
      }
    }
  };
});
